public class binarytrees {

    private static final class Node {
        final Node left;
        final Node right;

        Node(Node left, Node right) {
            this.left = left;
            this.right = right;
        }
    }

    private static Node bottomUpTree(int depth) {
        if (depth <= 0) {
            return new Node(null, null);
        }
        return new Node(bottomUpTree(depth - 1), bottomUpTree(depth - 1));
    }

    private static int itemCheck(Node node) {
        if (node.left == null) {
            return 1;
        }
        return 1 + itemCheck(node.left) + itemCheck(node.right);
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);
        StringBuilder out = new StringBuilder(1 << 14);

        int stretchDepth = n + 1;
        Node stretch = bottomUpTree(stretchDepth);
        out.append("stretch tree of depth ").append(stretchDepth)
           .append('\t').append(" check: ").append(itemCheck(stretch)).append('\n');
        stretch = null;

        Node longLivedTree = bottomUpTree(n);

        for (int depth = 4; depth <= n; depth += 2) {
            int iterations = 1 << (n - depth + 4);
            int check = 0;
            for (int i = 0; i < iterations; i++) {
                Node t = bottomUpTree(depth);
                check += itemCheck(t);
